def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

    axis = None
    for r in range(h):
        if all(v == 2 for v in grid[r]):
            axis = ("h", r)
            break
    if axis is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                axis = ("v", c)
                break
    if axis is None:
        return out

    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
              if grid[r][c] != background and grid[r][c] != 2]
    if not points:
        return out

    direction, pos = axis
    if direction == "h":
        top = min(r for r, c, v in points)
        bottom = max(r for r, c, v in points)
        if bottom < pos:
            dr = pos - 1 - bottom
            trace = top + dr - 1
        elif top > pos:
            dr = pos + 1 - top
            trace = bottom + dr + 1
        else:
            return out
        for r, c, v in points:
            out[r][c] = background
        for r, c, v in points:
            out[r + dr][c] = v
        if 0 <= trace < h:
            out[trace] = [8] * w
    else:
        left = min(c for r, c, v in points)
        right = max(c for r, c, v in points)
        if right < pos:
            dc = pos - 1 - right
            trace = left + dc - 1
        elif left > pos:
            dc = pos + 1 - left
            trace = right + dc + 1
        else:
            return out
        for r, c, v in points:
            out[r][c] = background
        for r, c, v in points:
            out[r][c + dc] = v
        if 0 <= trace < w:
            for r in range(h):
                out[r][trace] = 8
    return out

